import json
d=json.load(open('run3.json'))
ev=d['evidence']
for m in ev.get('materials',[]):
    for x in m['materials']:
        if x.get('material_number')=='HZ-6932' and (x.get('conditions') or x.get('condition_records_total')):
            print(m['url'][-60:], x.get('condition_records_total'), json.dumps(x.get('conditions'))[:300])
print('---- mail lists')
for l in ev.get('mail_list',[]):
    print(l['url'][-70:], l.get('folder'), len(l.get('messages',[])))
    for m in l.get('messages',[]): print('   ', m.get('subject'), '|', m.get('url'))
print('---- messages')
for m in ev.get('mail_message',[]): print(m['url'][-50:], '|', m.get('subject'), '|', m.get('topic'))
EOF

