        p = (root / p).resolve()
    else:
        p = p.resolve()
    if not p.exists() or not p.is_dir():
        raise ValueError(f"package does not exist: {arg}")
    try:
        p.relative_to(root)
    except ValueError:
        raise ValueError(f"package must be inside repo: {arg}")
    return p


