import json
lines=[]
for raw in open("run_f33ba.jsonl"):
    try: rec=json.loads(raw)
    except ValueError: continue
    for part in rec.get("text","").splitlines():
        lines.append(part)
open("run_f33ba_full.log","w").write("\n".join(lines))
evs=[]
for l in lines:
    if l.startswith("{"):
        try: evs.append(json.loads(l))
        except ValueError: pass
for e in evs:
    ev=e.get("event")
    if ev in ("llm","extracted","guard_overlays","trace"): continue
    if ev=="action":
        print(round(e["t"]), e["mission"], e["step"], e["tool"], json.dumps(e["args"],ensure_ascii=False)[:90], "->", e["result"][:110].replace("\n"," "))
    else:
        print(round(e["t"]), ev, json.dumps({k:v for k,v in e.items() if k not in ("t","event")},ensure_ascii=False)[:200])
EOF

